# Linker version script for the ihs_carla_bridge dart:ffi module. Export ONLY
# the flat C ABI; localize everything else -- including std::thread's
# vague-linkage internals and the vendored Dart DL API -- so the .so's dynamic
# symbol table is exactly the ihs_carla_bridge_* functions.
{
  global:
    ihs_carla_bridge_create;
    ihs_carla_bridge_start;
    ihs_carla_bridge_stop;
    ihs_carla_bridge_destroy;
    ihs_carla_bridge_init_dart_api;
    ihs_carla_bridge_set_event_port;
  local:
    *;
};
